<?php get_header(); ?>
<header class="page-hero"><div class="wrap"><p class="eyebrow"><?php esc_html_e('Travel journal', 'travel-riddle'); ?></p><h1><?php echo is_archive() ? esc_html(get_the_archive_title()) : esc_html__('Stories', 'travel-riddle'); ?></h1></div></header>
<section class="section"><div class="wrap post-list"><?php if (have_posts()) : while (have_posts()) : the_post(); ?><article><a href="<?php the_permalink(); ?>"><?php if (has_post_thumbnail()) { the_post_thumbnail('travel-riddle-card'); } ?></a><div class="post-list__body"><p class="eyebrow"><?php echo esc_html(travel_riddle_reading_time()); ?> min read</p><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(wp_trim_words(wp_strip_all_tags(get_the_content()), 24, '…')); ?></p></div></article><?php endwhile; the_posts_pagination(); else : ?><p><?php esc_html_e('New stories are on their way.', 'travel-riddle'); ?></p><?php endif; ?></div></section>
<?php get_footer(); ?>
